local unpacked,code=pcall(function()return inflate(descramble(decode(payload)))end)
payload=nil
if not unpacked then log('DECODE ERROR: '..tostring(code));return end
if #code~=461981 then log('DECODE ERROR: source length mismatch');return end
if type(loadstring)~='function' then log('loadstring unavailable in this executor');return end
log('Stage 3: compiling '..#code..' bytes')
local program,err=loadstring(code);code=nil
if not program then log('COMPILE ERROR: '..tostring(err));return end
log('Stage 4: launching JcHub, Steal Panel, Scanner & Watcher, task engine')
